'use client';
import React, { useRef } from 'react';
import Blocks from '@/components/ui/blocks';

function BlockOne() {
  const containerRef = useRef<HTMLDivElement>(null);
  return (
    <div
      className='h-[550px] overflow-hidden dark:bg-black bg-white before:absolute before:w-full before:h-full before:bg-linear-to-t  dark:before:from-[#070707] before:from-[#dbdbdb] before:z-1  w-full  relative'
      ref={containerRef}
    >
      <Blocks
        activeDivsClass='dark:bg-[#131212]  bg-[#9ba1a131]  '
        divClass='dark:border-[#131212] border-[#9ba1a131] '
        classname='w-full'
        containerRef={containerRef}
        activeDivs={{
          0: new Set([2, 4, 6]),
          1: new Set([0, 8]),
          2: new Set([1, 3, 5]),
          4: new Set([0, 5, 8]),
          5: new Set([2, 4]),
          7: new Set([2, 6, 9]),
          8: new Set([0, 4]),
          9: new Set([5]),
          10: new Set([3, 6]),
          11: new Set([1, 5]),
          12: new Set([7]),
          13: new Set([2, 4]),
          14: new Set([5]),
          15: new Set([1, 6]),
        }}
      />
    </div>
  );
}

export default BlockOne;

'use client';
import { cn } from '@/lib/utils';
import type React from 'react';
import { type JSX, useEffect, useState } from 'react';

function Blocks({
  activeDivs,
  divClass,
  classname,
  activeDivsClass,
  containerRef,
}: {
  activeDivsClass?: string;
  activeDivs?: any;
  divClass?: string;
  classname?: string;
  containerRef: React.RefObject<HTMLDivElement | null>;
}) {
  const [blocks, setBlocks] = useState<JSX.Element[]>([]);

  useEffect(() => {
    const updateBlocks = () => {
      const container = containerRef.current;
      if (container) {
        const containerWidth = container.clientWidth;
        const containerHeight = container.clientHeight;
        const blockSize = containerWidth * 0.06; // Using 6% of section width for the block size

        const columns = Math.floor(containerWidth / blockSize);
        const rows = Math.floor(containerHeight / blockSize);

        const newBlocks = Array.from({ length: columns }, (_, columnIndex) => (
          <div key={columnIndex} className='w-[6vw] h-full'>
            {Array.from({ length: rows }, (_, rowIndex) => (
              <div
                key={rowIndex}
                className={cn(
                  `h-[6vh] w-full border border-[#5dcece09] ${
                    activeDivs[columnIndex]?.has(rowIndex) ? `${activeDivsClass}` : ''
                  }`,
                  divClass
                )}
                style={{ height: `${blockSize}px` }}
              ></div>
            ))}
          </div>
        ));

        setBlocks(newBlocks);
      }
    };

    updateBlocks();
    window.addEventListener('resize', updateBlocks);

    return () => window.removeEventListener('resize', updateBlocks);
  }, [activeDivs, activeDivsClass, divClass, containerRef]);

  return (
    <div className={cn('flex h-full overflow-hidden top-0 -inset-0 left-0 absolute', classname)}>
      {blocks}
    </div>
  );
}

export default Blocks;
